/** A raw RGBA pixel buffer. The only image representation the core uses. */
export interface Pixels {
  data: Uint8ClampedArray;
  width: number;
  height: number;
}

/** An 8-bit RGB triple, 0-255 per channel. */
export type RGB = [number, number, number];

/** Ordered-dither threshold matrices. Used both by effects and by the mask gate. */
export type MatrixKind = "bayer2" | "bayer4" | "bayer8" | "blueNoise";

/** Which property of the source image the mask is derived from. */
export type MaskSourceKind = "luminance" | "saturation" | "gradient" | "external";

export type BlendMode = "normal" | "multiply" | "screen" | "overlay";

/** `mono` draws the effect in two flat colors; `source` keeps the source colors. */
export type ColorMode = "mono" | "source";

/**
 * Fully resolved mask options. Always computed from the UNDITHERED source.
 * `dither` is the matrix used to threshold the mask coverage; it is deliberately
 * independent of the effect matrix so switching effects cannot change the mask.
 */
export interface MaskOptions {
  source: MaskSourceKind;
  /** Lower edge of the accepted band, 0-1, in the mask source own units. */
  low: number;
  /** Upper edge of the accepted band, 0-1. */
  high: number;
  /** Width of the linear ramp at each band edge, 0-1, in VALUE units, not pixels. */
  softness: number;
  invert: boolean;
  dither: MatrixKind;
  /** Required when `source` is "external". Its luminance becomes the coverage. */
  external?: Pixels;
}

export interface DitherEffect {
  kind: "dither";
  matrix: MatrixKind;
  /** Number of output levels per channel, >= 2. */
  levels: number;
  /** Integer >= 1. Scales the matrix up so one cell covers `scale` pixels. */
  scale: number;
  color: ColorMode;
}

export interface HalftoneEffect {
  kind: "halftone";
  /** Cell size in pixels, >= 2. */
  cell: number;
  /** Screen angle in degrees. */
  angle: number;
  shape: "circle" | "square";
  color: ColorMode;
}

export interface AsciiEffect {
  kind: "ascii";
  cellWidth: number;
  cellHeight: number;
  /** Glyphs ordered darkest to lightest. */
  ramp: string;
  /** A CSS font shorthand, e.g. "12px monospace". */
  font: string;
  color: ColorMode;
}

export type EffectOptions = DitherEffect | HalftoneEffect | AsciiEffect;

export type EffectInput =
  | ({ kind: "dither" } & Partial<Omit<DitherEffect, "kind">>)
  | ({ kind: "halftone" } & Partial<Omit<HalftoneEffect, "kind">>)
  | ({ kind: "ascii" } & Partial<Omit<AsciiEffect, "kind">>);

export interface InkmaskOptions {
  mask?: Partial<MaskOptions>;
  effect?: EffectInput;
  blend?: BlendMode;
  /** 0-1, applied after the binary mask gate. */
  opacity?: number;
  /** Hex color, e.g. "#000000". Used by `mono` effects. */
  foreground?: string;
  background?: string;
}

export interface InkmaskResult {
  pixels: Pixels;
  /** Continuous mask coverage, 0-1, length width*height, BEFORE thresholding. */
  coverage: Float32Array;
  /** The thresholded mask. Contains only 0 and 1. Length width*height. */
  gate: Uint8Array;
}

import type { Pixels, RGB } from "./types.js";

/** An sRGB channel value in 0-1, converted to linear-light 0-1. */
export function srgbToLinear(c: number): number {
  return c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
}

/** Linear-light 0-1 back to gamma-encoded sRGB 0-1. */
export function linearToSrgb(c: number): number {
  return c <= 0.0031308 ? c * 12.92 : 1.055 * c ** (1 / 2.4) - 0.055;
}

/** Rec.709 relative luminance in 0-1, from 8-bit sRGB channels. Converts to linear FIRST. */
export function relativeLuminance(r: number, g: number, b: number): number {
  return (
    0.2126 * srgbToLinear(r / 255) +
    0.7152 * srgbToLinear(g / 255) +
    0.0722 * srgbToLinear(b / 255)
  );
}

/** Chroma-over-max saturation in 0-1, computed on LINEAR RGB, from 8-bit sRGB channels. */
export function saturation(r: number, g: number, b: number): number {
  // Saturation is computed on linear RGB for consistency with the luminance path.
  const lr = srgbToLinear(r / 255);
  const lg = srgbToLinear(g / 255);
  const lb = srgbToLinear(b / 255);
  const max = Math.max(lr, lg, lb);
  const min = Math.min(lr, lg, lb);
  return max <= 0 ? 0 : (max - min) / max;
}

/** Per-pixel Rec.709 linear luminance. Length is width*height. */
export function luminanceField(px: Pixels): Float32Array {
  const { data, width, height } = px;
  const out = new Float32Array(width * height);
  for (let i = 0, j = 0; i < out.length; i++, j += 4) {
    out[i] = relativeLuminance(data[j]!, data[j + 1]!, data[j + 2]!);
  }
  return out;
}

/** Per-pixel saturation. Length is width*height. */
export function saturationField(px: Pixels): Float32Array {
  const { data, width, height } = px;
  const out = new Float32Array(width * height);
  for (let i = 0, j = 0; i < out.length; i++, j += 4) {
    out[i] = saturation(data[j]!, data[j + 1]!, data[j + 2]!);
  }
  return out;
}

/** Parse "#rgb" or "#rrggbb" into an RGB triple. Throws on any other input. */
export function parseHex(hex: string): RGB {
  if (/^#[0-9a-fA-F]{3}$/.test(hex)) {
    const r = parseInt(hex.charAt(1) + hex.charAt(1), 16);
    const g = parseInt(hex.charAt(2) + hex.charAt(2), 16);
    const b = parseInt(hex.charAt(3) + hex.charAt(3), 16);
    return [r, g, b];
  }
  if (/^#[0-9a-fA-F]{6}$/.test(hex)) {
    const r = parseInt(hex.slice(1, 3), 16);
    const g = parseInt(hex.slice(3, 5), 16);
    const b = parseInt(hex.slice(5, 7), 16);
    return [r, g, b];
  }
  throw new Error(`Invalid hex color: ${hex}`);
}

import type { MatrixKind } from "./types.js";
import { BLUE_NOISE_64 } from "./bluenoise-data.js";

const B2: number[][] = [
  [0, 2],
  [3, 1],
];

/** Side length of the matrix: 2, 4, 8, or 64. */
export function matrixSize(kind: MatrixKind): number {
  switch (kind) {
    case "bayer2":
      return 2;
    case "bayer4":
      return 4;
    case "bayer8":
      return 8;
    case "blueNoise":
      return 64;
  }
}

const cache = new Map<MatrixKind, Uint16Array>();

/** Build Bayer matrix of side 2n from Bn via standard recursion. */
function bayerFrom(Bn: Uint16Array, n: number): Uint16Array {
  const side = 2 * n;
  const out = new Uint16Array(side * side);
  for (let y = 0; y < side; y++) {
    for (let x = 0; x < side; x++) {
      const base = Bn[(y % n) * n + (x % n)]!;
      const q = B2[(y / n) | 0]![(x / n) | 0]!;
      out[y * side + x] = 4 * base + q;
    }
  }
  return out;
}

function buildBayer2(): Uint16Array {
  return new Uint16Array([0, 2, 3, 1]);
}

function buildMatrix(kind: MatrixKind): Uint16Array {
  switch (kind) {
    case "bayer2":
      return buildBayer2();
    case "bayer4":
      return bayerFrom(buildBayer2(), 2);
    case "bayer8":
      return bayerFrom(bayerFrom(buildBayer2(), 2), 4);
    case "blueNoise":
      return BLUE_NOISE_64;
  }
}

/** The raw rank matrix, row-major. Values are a permutation of 0..n*n-1. */
export function rankMatrix(kind: MatrixKind): Uint16Array {
  let m = cache.get(kind);
  if (!m) {
    m = buildMatrix(kind);
    cache.set(kind, m);
  }
  return m;
}

/** Normalized threshold, strictly between 0 and 1, tiling with period matrixSize(kind). */
export function thresholdAt(kind: MatrixKind, x: number, y: number): number {
  const n = matrixSize(kind);
  const m = rankMatrix(kind);
  const ix = ((x % n) + n) % n;
  const iy = ((y % n) + n) % n;
  const rank = m[iy * n + ix]!;
  return (rank + 0.5) / (n * n);
}

import type { MaskOptions, MatrixKind, Pixels } from "./types.js";
import { luminanceField, saturationField } from "./color.js";
import { thresholdAt } from "./matrix.js";

/**
 * Continuous mask coverage in 0-1, computed from the UNDITHERED source.
 * Length is width*height. Deliberately has no knowledge of the effect.
 */
export function computeCoverage(src: Pixels, opts: MaskOptions): Float32Array {
  const { width, height } = src;
  const n = width * height;
  const field = sourceField(src, opts);
  const out = new Float32Array(n);
  const s = opts.softness;
  const low = opts.low;
  const high = opts.high;
  const inv = opts.invert;

  // softness is a ramp width in VALUE units (source-field 0-1), not pixels.
  // Spatial feathering is intentionally absent; the ordered-dither gate
  // produces the dotted falloff after this pure per-pixel band map.
  for (let i = 0; i < n; i++) {
    const v = field[i]!;
    let c: number;
    if (s <= 0) {
      c = v >= low && v <= high ? 1 : 0;
    } else {
      c = Math.min((v - (low - s)) / s, (high + s - v) / s);
      if (c < 0) c = 0;
      else if (c > 1) c = 1;
    }
    out[i] = inv ? 1 - c : c;
  }
  return out;
}

/** Mean coverage per cell. cols/rows use ceil, so partial edge cells are included. */
export function resolveMaskToCells(
  coverage: Float32Array,
  width: number,
  height: number,
  cellWidth: number,
  cellHeight: number,
): { cells: Float32Array; cols: number; rows: number } {
  const cols = Math.ceil(width / cellWidth);
  const rows = Math.ceil(height / cellHeight);
  const cells = new Float32Array(cols * rows);

  for (let cy = 0; cy < rows; cy++) {
    const y0 = cy * cellHeight;
    const y1 = Math.min(y0 + cellHeight, height);
    for (let cx = 0; cx < cols; cx++) {
      const x0 = cx * cellWidth;
      const x1 = Math.min(x0 + cellWidth, width);
      let sum = 0;
      let count = 0;
      for (let y = y0; y < y1; y++) {
        const row = y * width;
        for (let x = x0; x < x1; x++) {
          sum += coverage[row + x]!;
          count++;
        }
      }
      cells[cy * cols + cx] = count > 0 ? sum / count : 0;
    }
  }
  return { cells, cols, rows };
}

/** Threshold coverage per pixel against an ordered matrix. Contains only 0 and 1. */
export function thresholdCoverage(
  coverage: Float32Array,
  width: number,
  height: number,
  matrix: MatrixKind,
): Uint8Array {
  const out = new Uint8Array(width * height);
  for (let y = 0; y < height; y++) {
    const row = y * width;
    for (let x = 0; x < width; x++) {
      const i = row + x;
      out[i] = coverage[i]! > thresholdAt(matrix, x, y) ? 1 : 0;
    }
  }
  return out;
}

/**
 * Cell-resolved gate for glyph effects. Coverage is averaged per cell and
 * thresholded once per cell, indexed by CELL coordinates, so no cell is ever
 * partially masked. Returned length is still width*height, constant per cell.
 */
export function thresholdCoverageByCell(
  coverage: Float32Array,
  width: number,
  height: number,
  cellWidth: number,
  cellHeight: number,
  matrix: MatrixKind,
): Uint8Array {
  const { cells, cols, rows } = resolveMaskToCells(
    coverage,
    width,
    height,
    cellWidth,
    cellHeight,
  );
  const out = new Uint8Array(width * height);

  for (let cy = 0; cy < rows; cy++) {
    const y0 = cy * cellHeight;
    const y1 = Math.min(y0 + cellHeight, height);
    for (let cx = 0; cx < cols; cx++) {
      const gate = cells[cy * cols + cx]! > thresholdAt(matrix, cx, cy) ? 1 : 0;
      const x0 = cx * cellWidth;
      const x1 = Math.min(x0 + cellWidth, width);
      for (let y = y0; y < y1; y++) {
        const row = y * width;
        for (let x = x0; x < x1; x++) {
          out[row + x] = gate;
        }
      }
    }
  }
  return out;
}

function sourceField(src: Pixels, opts: MaskOptions): Float32Array {
  switch (opts.source) {
    case "luminance":
      return luminanceField(src);
    case "saturation":
      return saturationField(src);
    case "gradient":
      return sobelMagnitude(luminanceField(src), src.width, src.height);
    case "external": {
      const ext = opts.external;
      if (!ext) {
        throw new RangeError('Mask source "external" requires opts.external');
      }
      if (ext.width !== src.width || ext.height !== src.height) {
        throw new RangeError(
          `External mask dimensions ${ext.width}x${ext.height} differ from source ${src.width}x${src.height}`,
        );
      }
      return luminanceField(ext);
    }
  }
}

/** Sobel magnitude of a scalar field. Fixed 0-1 normalization; edge coords clamp. */
function sobelMagnitude(
  field: Float32Array,
  width: number,
  height: number,
): Float32Array {
  const out = new Float32Array(width * height);
  const inv = 1 / (4 * Math.SQRT2);

  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const sample = (dx: number, dy: number): number => {
        let sx = x + dx;
        let sy = y + dy;
        if (sx < 0) sx = 0;
        else if (sx >= width) sx = width - 1;
        if (sy < 0) sy = 0;
        else if (sy >= height) sy = height - 1;
        return field[sy * width + sx]!;
      };

      // gx = [[-1,0,1],[-2,0,2],[-1,0,1]], gy = transpose
      const gx =
        -sample(-1, -1) +
        sample(1, -1) +
        -2 * sample(-1, 0) +
        2 * sample(1, 0) +
        -sample(-1, 1) +
        sample(1, 1);
      const gy =
        -sample(-1, -1) +
        -2 * sample(0, -1) +
        -sample(1, -1) +
        sample(-1, 1) +
        2 * sample(0, 1) +
        sample(1, 1);

      let m = Math.sqrt(gx * gx + gy * gy) * inv;
      if (m < 0) m = 0;
      else if (m > 1) m = 1;
      out[y * width + x] = m;
    }
  }
  return out;
}

import type { BlendMode, Pixels, RGB } from "./types.js";

/** Blend two 8-bit sRGB triples. Operates in sRGB space, as blend modes conventionally do. */
export function blendRGB(mode: BlendMode, base: RGB, effect: RGB): RGB {
  const out: RGB = [0, 0, 0];
  for (let i = 0; i < 3; i++) {
    const b = base[i]! / 255;
    const e = effect[i]! / 255;
    let r: number;
    switch (mode) {
      case "normal":
        r = e;
        break;
      case "multiply":
        r = b * e;
        break;
      case "screen":
        r = 1 - (1 - b) * (1 - e);
        break;
      case "overlay":
        r = b < 0.5 ? 2 * b * e : 1 - 2 * (1 - b) * (1 - e);
        break;
    }
    out[i] = Math.round(r * 255);
  }
  return out;
}

/**
 * Effect layer over base layer, gated by a binary mask.
 * `gate` contains only 0 and 1 and has length width*height.
 * Where gate is 0 the base pixel is copied through byte-identically.
 * Returns a new Pixels. Neither input is mutated. Base alpha is preserved.
 */
export function composite(
  base: Pixels,
  effect: Pixels,
  gate: Uint8Array,
  opts: { blend: BlendMode; opacity: number },
): Pixels {
  if (base.width !== effect.width || base.height !== effect.height) {
    throw new RangeError("base and effect dimensions must match");
  }
  if (gate.length !== base.width * base.height) {
    throw new RangeError("gate length must equal base.width * base.height");
  }

  const { blend, opacity } = opts;
  const n = base.width * base.height;
  const out = new Uint8ClampedArray(base.data.length);

  for (let i = 0; i < n; i++) {
    const o = i * 4;
    if (gate[i] === 0) {
      out[o] = base.data[o]!;
      out[o + 1] = base.data[o + 1]!;
      out[o + 2] = base.data[o + 2]!;
      out[o + 3] = base.data[o + 3]!;
      continue;
    }

    const blended = blendRGB(
      blend,
      [base.data[o]!, base.data[o + 1]!, base.data[o + 2]!],
      [effect.data[o]!, effect.data[o + 1]!, effect.data[o + 2]!],
    );
    out[o] = Math.round(base.data[o]! + (blended[0] - base.data[o]!) * opacity);
    out[o + 1] = Math.round(
      base.data[o + 1]! + (blended[1] - base.data[o + 1]!) * opacity,
    );
    out[o + 2] = Math.round(
      base.data[o + 2]! + (blended[2] - base.data[o + 2]!) * opacity,
    );
    out[o + 3] = base.data[o + 3]!;
  }

  return { data: out, width: base.width, height: base.height };
}

import type { DitherEffect, Pixels, RGB } from "./types.js";
import { relativeLuminance } from "./color.js";
import { thresholdAt } from "./matrix.js";

/**
 * Ordered-dither the entire source image.
 * Returns a new Pixels; the input is not mutated. Alpha is copied through.
 */
export function ditherEffect(src: Pixels, opts: DitherEffect, fg: RGB, bg: RGB): Pixels {
  const { data, width, height } = src;
  const out = new Uint8ClampedArray(data.length);
  const scale = opts.scale;
  const n = opts.levels;

  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const i = (y * width + x) * 4;
      const r = data[i]!;
      const g = data[i + 1]!;
      const b = data[i + 2]!;
      const a = data[i + 3]!;
      const t = thresholdAt(opts.matrix, Math.floor(x / scale), Math.floor(y / scale));

      if (opts.color === "mono") {
        const Y = relativeLuminance(r, g, b);
        const [or, og, ob] = Y > t ? bg : fg;
        out[i] = or;
        out[i + 1] = og;
        out[i + 2] = ob;
      } else {
        const denom = n - 1;
        const quant = (v: number): number => {
          let q = Math.floor((v / 255) * denom + t);
          if (q < 0) q = 0;
          else if (q > denom) q = denom;
          return Math.round((q / denom) * 255);
        };
        out[i] = quant(r);
        out[i + 1] = quant(g);
        out[i + 2] = quant(b);
      }
      out[i + 3] = a;
    }
  }

  return { data: out, width, height };
}

import type { HalftoneEffect, Pixels, RGB } from "./types.js";
import { relativeLuminance } from "./color.js";

/**
 * Render the entire source as a rotated halftone screen.
 * Returns a new Pixels; the input is not mutated. Alpha is copied through.
 */
export function halftoneEffect(src: Pixels, opts: HalftoneEffect, fg: RGB, bg: RGB): Pixels {
  const { data, width, height } = src;
  const out = new Uint8ClampedArray(data.length);
  const cell = opts.cell;
  const rad = (opts.angle * Math.PI) / 180;
  const cos = Math.cos(rad);
  const sin = Math.sin(rad);
  const sqrt2 = Math.SQRT2;
  const mono = opts.color === "mono";
  const circle = opts.shape === "circle";

  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const i = (y * width + x) * 4;

      // 1. Rotate into screen space
      const rx = x * cos + y * sin;
      const ry = -x * sin + y * cos;

      // 2. Locate the screen cell and its center
      const cx = Math.floor(rx / cell);
      const cy = Math.floor(ry / cell);
      const ccx = (cx + 0.5) * cell;
      const ccy = (cy + 0.5) * cell;

      // 3. Rotate center back into image space, sample luminance once per cell
      let sx = Math.round(ccx * cos - ccy * sin);
      let sy = Math.round(ccx * sin + ccy * cos);
      if (sx < 0) sx = 0;
      else if (sx >= width) sx = width - 1;
      if (sy < 0) sy = 0;
      else if (sy >= height) sy = height - 1;

      const si = (sy * width + sx) * 4;
      const sr = data[si]!;
      const sg = data[si + 1]!;
      const sb = data[si + 2]!;
      const L = relativeLuminance(sr, sg, sb);

      // 4. Size the dot from L (black fills cell; white is empty)
      const extent = (1 - L) * cell * 0.5 * sqrt2;
      let ink: boolean;
      if (circle) {
        const dx = rx - ccx;
        const dy = ry - ccy;
        ink = dx * dx + dy * dy <= extent * extent;
      } else {
        ink = Math.max(Math.abs(rx - ccx), Math.abs(ry - ccy)) <= extent;
      }

      // 5. Emit colors
      if (ink) {
        if (mono) {
          out[i] = fg[0];
          out[i + 1] = fg[1];
          out[i + 2] = fg[2];
        } else {
          out[i] = sr;
          out[i + 1] = sg;
          out[i + 2] = sb;
        }
      } else {
        out[i] = bg[0];
        out[i + 1] = bg[1];
        out[i + 2] = bg[2];
      }
      out[i + 3] = data[i + 3]!;
    }
  }

  return { data: out, width, height };
}

import type { AsciiEffect, Pixels, RGB } from "./types.js";
import { relativeLuminance } from "./color.js";

export interface AsciiGrid {
  cols: number;
  rows: number;
  /** One glyph per cell, row-major. Length cols*rows. */
  chars: string[];
  /** Mean source color per cell, row-major. Length cols*rows. */
  colors: RGB[];
}

/** Pure: map the source to a glyph grid. No DOM. */
export function asciiGrid(src: Pixels, opts: AsciiEffect): AsciiGrid {
  const { data, width, height } = src;
  const { cellWidth, cellHeight, ramp } = opts;
  // Same ceil geometry as resolveMaskToCells — partial edge cells are real cells.
  const cols = Math.ceil(width / cellWidth);
  const rows = Math.ceil(height / cellHeight);
  const chars: string[] = new Array(cols * rows);
  const colors: RGB[] = new Array(cols * rows);
  const last = ramp.length - 1;

  for (let cy = 0; cy < rows; cy++) {
    const y0 = cy * cellHeight;
    const y1 = Math.min(y0 + cellHeight, height);
    for (let cx = 0; cx < cols; cx++) {
      const x0 = cx * cellWidth;
      const x1 = Math.min(x0 + cellWidth, width);
      let sumL = 0;
      let sumR = 0;
      let sumG = 0;
      let sumB = 0;
      let count = 0;
      for (let y = y0; y < y1; y++) {
        const row = y * width;
        for (let x = x0; x < x1; x++) {
          const i = (row + x) * 4;
          const r = data[i]!;
          const g = data[i + 1]!;
          const b = data[i + 2]!;
          sumL += relativeLuminance(r, g, b);
          sumR += r;
          sumG += g;
          sumB += b;
          count++;
        }
      }
      const L = count > 0 ? sumL / count : 0;
      let idx = Math.round(L * last);
      if (idx < 0) idx = 0;
      else if (idx > last) idx = last;

      const ci = cy * cols + cx;
      chars[ci] = ramp.charAt(idx);
      colors[ci] = [
        Math.round(count > 0 ? sumR / count : 0),
        Math.round(count > 0 ? sumG / count : 0),
        Math.round(count > 0 ? sumB / count : 0),
      ];
    }
  }

  return { cols, rows, chars, colors };
}

// =============================================================================
// BROWSER ONLY — requires document/canvas. Not exercised by Node tests.
// asciiEffect is verified in the browser harness instead.
